    .replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
    .replace(/^-/, "[-−]");
  return new RegExp(`(^|[^0-9.\\-−])${escaped}($|[^0-9.\\-−])`);
}

function display(page) {
  return page.getByRole("status");
