  // viewport can show at most 568 / height of its area.
  for (const element of [...elements, ...(await page.getByRole("button").all())]) {
    await element.scrollIntoViewIfNeeded();
    const box = await element.boundingBox();
    const share = box && box.height > 568 ? (568 / box.height) * (1 - 1e-6) : 1;
    await expect(element).toBeInViewport({ ratio: share });
