const { test, expect } = await import(process.env.BW_PLAYWRIGHT_TEST);

const PROPS = ["background-color", "color", "outline-style", "outline-color", "border-color", "box-shadow"];

const setTheme = async (page, theme) => {
  const toggle = page.locator("#theme-toggle");
  const html = page.locator("html");
  await toggle.click();
  if ((await html.getAttribute("data-theme")) !== theme) {
    await toggle.click();
  }
  await expect(html).toHaveAttribute("data-theme", theme);
};

const styles = (locator) =>
  locator.evaluate((el, props) => {
    const s = getComputedStyle(el);
    const out = {};
    for (const p of props) {
      out[p] = s.getPropertyValue(p);
    }
    return out;
  }, PROPS);

// The first property whose value differs, or the first property when none does.
const differing = (before, after) => PROPS.find((p) => before[p] !== after[p]) ?? PROPS[0];

for (const theme of ["light", "dark"]) {
  test(`AC-022 For every calculator button and the theme control, in the ${theme} theme, a style property differs between the default state and the mouse-hover state, and between the default state and the Tab-focus state`, async ({ page }) => {
    await page.goto("index.html");
    await expect(page.locator("#theme-toggle")).toBeVisible();
    await setTheme(page, theme);
    await page.goto("index.html");
    await expect(page.locator("html")).toHaveAttribute("data-theme", theme);
    const buttons = await page.getByRole("button").all();
    for (const button of buttons) {
      await page.mouse.move(0, 0);
      const base = await styles(button);

      await button.hover();
      const hovered = await styles(button);
      const hoverProp = differing(base, hovered);
      await expect(button).not.toHaveCSS(hoverProp, base[hoverProp]);

      await page.mouse.move(0, 0);
      for (let i = 0; i < 2 * buttons.length + 2; i++) {
        if (await button.evaluate((el) => el === document.activeElement)) {
          break;
        }
        await page.keyboard.press("Tab");
      }
      await expect(button).toBeFocused();
      const focused = await styles(button);
      const focusProp = differing(base, focused);
      await expect(button).not.toHaveCSS(focusProp, base[focusProp]);
    }
  });
}

