test("AC-018 The page shows a theme control. After it is activated once, the data-theme attribute of the html element is either light or dark. Each further activation changes the attribute to the other of those two values, and the computed background-color of the body element when data-theme is light differs from its computed background-color when data-theme is dark", async ({ page }) => {
  await page.goto("index.html");
  const toggle = page.locator("#theme-toggle");
  const html = page.locator("html");
  const body = page.locator("body");
  await expect(toggle).toBeVisible();
  await toggle.click();
  await expect(html).toHaveAttribute("data-theme", /^(light|dark)$/);
  const first = await html.getAttribute("data-theme");
  const other = first === "light" ? "dark" : "light";
  const firstBg = await body.evaluate((el) => getComputedStyle(el).backgroundColor);
  await toggle.click();
  await expect(html).toHaveAttribute("data-theme", other);
  await expect(body).not.toHaveCSS("background-color", firstBg);
  const otherBg = await body.evaluate((el) => getComputedStyle(el).backgroundColor);
  await toggle.click();
  await expect(html).toHaveAttribute("data-theme", first);
  await expect(body).toHaveCSS("background-color", firstBg);
  await expect(body).not.toHaveCSS("background-color", otherBg);
});

